catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
   if (isLoading || newValue == '') {
      return;
   }

   var today = new Date();
   today.setHours(0,0,0,0);
   //console.log("ué?");

    // Converter a data de despesa para um objeto Date
    var expenseDate = new Date(newValue);


    if (expenseDate > today) {

        g_form.addErrorMessage('The expense date cannot be in the future.');


        g_form.setValue('expense_date', '');
    } else {

        g_form.hideFieldMsg('expense_date');
    }
}

